// energy/degradation sketch for: openLCA
let c = 1.0; const samples = [];
for (let i = 0; i < 541; i++) { c *= 0.99966; if (i % 100 === 0) samples.push(+c.toFixed(4)); }
console.log(JSON.stringify({ cycles: 541, retention: +c.toFixed(4), samples: samples,
  eolReached: c < 0.8 }));

